const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const paths = ['src/s01.cjs', 'runner.cjs', 'sentinel.txt'];
const digest = () => paths.map(p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex'));
const before = digest();
const runner = fs.readFileSync('runner.cjs', 'utf8');
const cases = [
  ['numeric42', 'module.exports = { answer: 42 };', 0, 'ok 2 - answer is 42'],
  ['numeric0', fs.readFileSync('src/s01.cjs', 'utf8'), 1, 'not ok 2 - answer is 42'],
  ['string42', 'module.exports = { answer: \"42\" };', 1, 'not ok 2 - answer is 42'],
  ['missing', 'module.exports = {};', 1, 'not ok 2 - answer is 42']
];
for (const [name, source, expectedCode, expectedLine] of cases) {
  const mod = { exports: {} };
  vm.runInNewContext(source, { module: mod });
  let output = '';
  let artifact = '';
  const processStub = { stdout: { write: value => { output += value; } }, exitCode: undefined };
  const fsStub = {
    readFileSync: (p, encoding) => { assert.equal(p, './src/s01.cjs'); assert.equal(encoding, 'utf8'); return source; },
    writeFileSync: (p, value) => { assert.equal(p, 'report.tap'); artifact = value; }
  };
  vm.runInNewContext(runner, { require: p => {
    if (p === 'node:fs') return fsStub;
    assert.equal(p, './src/s01.cjs');
    return mod.exports;
  }, process: processStub });
  assert.equal(processStub.exitCode, expectedCode);
  assert.equal(artifact, output);
  assert.ok(output.split('\\n').includes('ok 1 - fixture module loads'));
  assert.ok(output.split('\\n').includes(expectedLine));
  assert.ok(output.split('\\n').includes('1..2'));
  console.log(name + ': exit ' + processStub.exitCode + ', expected TAP case result confirmed');
}
assert.deepEqual(digest(), before);
console.log('Declared source, runner, and sentinel bytes unchanged.');
